using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class PostTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    public PostTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool, Description("Get a post by its ID.")]
    public async Task<string> GetPost(
        [Description("The numeric post ID (1-100).")] int id)
    {
        using var client = _httpClientFactory.CreateClient("api");
        var post = await client.GetFromJsonAsync<Post>($"/posts/{id}");
        return post is null
            ? "Post not found."
            : $"Title: {post.Title}\n\n{post.Body}";
    }

    [McpServerTool, Description("List posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Optional user ID to filter posts.")] int? userId = null)
    {
        using var client = _httpClientFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var posts = await client.GetFromJsonAsync<Post[]>(url);
        if (posts is null || posts.Length == 0)
            return "No posts found.";

        return string.Join("\n", posts.Select(p => $"[{p.Id}] {p.Title}"));
    }

    [McpServerTool, Description("Create a new post.")]
    public async Task<string> CreatePost(
        [Description("The user ID authoring the post.")] int userId,
        [Description("The post title.")] string title,
        [Description("The post body text.")] string body)
    {
        using var client = _httpClientFactory.CreateClient("api");
        var response = await client.PostAsJsonAsync("/posts", new { userId, title, body });
        response.EnsureSuccessStatusCode();
        var created = await response.Content.ReadFromJsonAsync<Post>();
        return $"Created post with ID {created?.Id}.";
    }
}

internal sealed class Post
{
    [JsonPropertyName("id")]
    public int Id { get; set; }

    [JsonPropertyName("userId")]
    public int UserId { get; set; }

    [JsonPropertyName("title")]
    public string Title { get; set; } = "";

    [JsonPropertyName("body")]
    public string Body { get; set; } = "";
}

